  str_aircraft_desc_7101003 = "A Colossus pode ser operada da Ponte. Ela oferece uma linda vista e ampla visão e é essencial para <color=#00F6FF>liberar o acesso aos privilégios</color>, bem como o Ânimo na Colossus. Certos Aurorians também podem aumentar <color=#00F6FF>o Ânimo ao mobiliar</color> a Colossus.",
  str_aircraft_desc_7101004 = "A Colossus pode ser operada da Ponte. Ela oferece uma linda vista e ampla visão e é essencial para <color=#00F6FF>liberar o acesso aos privilégios</color>, bem como o Ânimo na Colossus. Certos Aurorians também podem aumentar <color=#00F6FF>o Ânimo ao mobiliar</color> a Colossus.",
  str_aircraft_desc_7101005 = "A Colossus pode ser operada da Ponte. Ela oferece uma linda vista e ampla visão e é essencial para <color=#00F6FF>liberar o acesso aos privilégios</color>, bem como o Ânimo na Colossus. Certos Aurorians também podem aumentar <color=#00F6FF>o Ânimo ao mobiliar</color> a Colossus.",
  str_aircraft_desc_7102001 = "A Sala Lúmina serve como gerador de energia da Colossus, <color=#00F6FF>fornecendo lúmina para todos os ambientes</color>. Também é o lugar predileto dos Vaga-lumes, você consegue aumentar a <color=#00F6FF>velocidade de recuperação dos Vaga-lumes</color> aqui. Certos Aurorians adoram Vaga-lumes e podem aumentar mais a velocidade de <color=#00F6FF>recuperação deles</color>.",
