  str_aircraft_desc_7102004 = "A Sala Lúmina serve como gerador de energia da Colossus, <color=#00F6FF>fornecendo lúmina para todos os ambientes</color>. Também é o lugar predileto dos Vaga-lumes, você consegue aumentar a <color=#00F6FF>velocidade de recuperação dos Vaga-lumes</color> aqui. Certos Aurorians adoram Vaga-lumes e podem aumentar mais a velocidade de <color=#00F6FF>recuperação deles</color>.",
  str_aircraft_desc_7102005 = "A Sala Lúmina serve como gerador de energia da Colossus, <color=#00F6FF>fornecendo lúmina para todos os ambientes</color>. Também é o lugar predileto dos Vaga-lumes, você consegue aumentar a <color=#00F6FF>velocidade de recuperação dos Vaga-lumes</color> aqui. Certos Aurorians adoram Vaga-lumes e podem aumentar mais a velocidade de <color=#00F6FF>recuperação deles</color>.",
  str_aircraft_desc_7103001 = "Os <color=#00F6FF>MS no Luminômetro</color> são vitais para a exploração do Território Secreto. O Sol Artificial daqui recarrega o Luminômetro, <color=#00F6FF>fornecendo e restaurando MS</color>. Certos Aurorians são apaixonados por exploração e podem aumentar a <color=#00F6FF>taxa de recuperação de MS</color>.",
  str_aircraft_desc_7103002 = "Os <color=#00F6FF>MS no Luminômetro</color> são vitais para a exploração do Território Secreto. O Sol Artificial daqui recarrega o Luminômetro, <color=#00F6FF>fornecendo e restaurando MS</color>. Certos Aurorians são apaixonados por exploração e podem aumentar a <color=#00F6FF>taxa de recuperação de MS</color>.",
  str_aircraft_desc_7103003 = "Os <color=#00F6FF>MS no Luminômetro</color> são vitais para a exploração do Território Secreto. O Sol Artificial daqui recarrega o Luminômetro, <color=#00F6FF>fornecendo e restaurando MS</color>. Certos Aurorians são apaixonados por exploração e podem aumentar a <color=#00F6FF>taxa de recuperação de MS</color>.",
  str_aircraft_desc_7103004 = "Os <color=#00F6FF>MS no Luminômetro</color> são vitais para a exploração do Território Secreto. O Sol Artificial daqui recarrega o Luminômetro, <color=#00F6FF>fornecendo e restaurando MS</color>. Certos Aurorians são apaixonados por exploração e podem aumentar a <color=#00F6FF>taxa de recuperação de MS</color>.",
  str_aircraft_desc_7103005 = "Os <color=#00F6FF>MS no Luminômetro</color> são vitais para a exploração do Território Secreto. O Sol Artificial daqui recarrega o Luminômetro, <color=#00F6FF>fornecendo e restaurando MS</color>. Certos Aurorians são apaixonados por exploração e podem aumentar a <color=#00F6FF>taxa de recuperação de MS</color>.",
  str_aircraft_desc_7104001 = "Você pode <color=#00F6FF>fabricar transportadores</color> aqui em intervalos de tempo específicos, o que reduz a quantidade de Prisma necessária para limpar o palco e concede seu rendimento imediatamente ao usar o Sweep. Certos aurorianos até possuem Luminatics que podem <color=#00F6FF>aumentar a velocidade de fabricação da Carrier</color>.",
  str_aircraft_desc_7104002 = "Você pode <color=#00F6FF>fabricar transportadores</color> aqui em intervalos de tempo específicos, o que reduz a quantidade de Prisma necessária para limpar o palco e concede seu rendimento imediatamente ao usar o Sweep. Certos aurorianos até possuem Lumináticos que podem <color=#00F6FF>aumentar a velocidade de fabricação da Carrier</color>.",
  str_aircraft_desc_7104003 = "Você pode <color=#00F6FF>fabricar transportadores</color> aqui em intervalos de tempo específicos, o que reduz a quantidade de Prisma necessária para limpar o palco e concede seu rendimento imediatamente ao usar o Sweep. Certos aurorianos até possuem Lumináticos que podem <color=#00F6FF>aumentar a velocidade de fabricação da Carrier</color>.",
  str_aircraft_desc_7104004 = "Você pode <color=#00F6FF>fabricar transportadores</color> aqui em intervalos de tempo específicos, o que reduz a quantidade de Prisma necessária para limpar o palco e concede seu rendimento imediatamente ao usar o Sweep. Certos aurorianos até possuem Lumináticos que podem <color=#00F6FF>aumentar a velocidade de fabricação da Carrier</color>.",
  str_aircraft_desc_7104005 = "Você pode <color=#00F6FF>fabricar transportadores</color> aqui em intervalos de tempo específicos, o que reduz a quantidade de Prisma necessária para limpar o palco e concede seu rendimento imediatamente ao usar o Sweep. Certos aurorianos até possuem Luminatics que podem <color=#00F6FF>aumentar a velocidade de fabricação da Carrier</color>.",
  str_aircraft_desc_7105001 = "O Pilar Prisma é onde o <color=#00F6FF>Prisma é armazenado</color>, e também permite que você use Lúmina para <color=#00F6FF>ganhar Prisma</color>. Quanto maior seu nível de Pilar Prisma, mais rápido você acumulará Prisma. Pilares Prisma avançados também podem <color=#00F6FF>aumentar sua capacidade máxima de Prisma</color>. Certos Aurorians possuem Lumináticas que permitem <color=#00F6FF>melhorar a taxa de aquisição de Prisma</color>.",
  str_aircraft_desc_7105002 = "O Pilar Prisma é onde o <color=#00F6FF>Prisma é armazenado</color>, e também permite que você use Lúmina para <color=#00F6FF>ganhar Prisma</color>. Quanto maior seu nível de Pilar Prisma, mais rápido você acumulará Prisma. Pilares Prisma avançados também podem <color=#00F6FF>aumentar sua capacidade máxima de Prisma</color>. Certos Aurorians possuem Lumináticas que permitem <color=#00F6FF>melhorar a taxa de aquisição de Prisma</color>.",
